CREATE OR REPLACE FUNCTION public.review_prime99(_id uuid,_approve boolean,_note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.prime99_payments; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO p FROM public.prime99_payments WHERE id=_id FOR UPDATE; IF p.id IS NULL OR p.status<>'pending' THEN RAISE EXCEPTION 'NO_PENDING_PAYMENT'; END IF; PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; UPDATE public.prime99_payments SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,received_at=CASE WHEN _approve THEN now() ELSE NULL END,ends_at=CASE WHEN _approve THEN now()+interval '1 month' ELSE NULL END,reviewed_by=auth.uid(),review_note=left(coalesce(_note,''),500) WHERE id=_id; IF _approve THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(p.user_id,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at WHERE monthly_post_periods.ends_at<=now(); PERFORM public.confirm_referral_cash(p.user_id,p.reference,9900); END IF; END $$;
CREATE OR REPLACE FUNCTION public.dispatch_daily_referral_board() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person record; notice uuid; board jsonb; today date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; n integer:=0; leader text; BEGIN board:=public.public_referral_vip_board(); leader:=coalesce(board->'rows'->0->>'name',''); FOR person IN SELECT p.id FROM public.profiles p WHERE public.can_notify(p.id) AND NOT EXISTS(SELECT 1 FROM public.daily_referral_board_notices d WHERE d.user_id=p.id AND d.day=today) ORDER BY p.id LIMIT 200 LOOP PERFORM 1 FROM public.profiles WHERE id=person.id FOR UPDATE; IF public.can_notify(person.id) THEN INSERT INTO public.daily_referral_board_notices(user_id,day) VALUES(person.id,today) ON CONFLICT DO NOTHING; IF FOUND THEN notice:=NULL; INSERT INTO public.notifications(user_id,message) VALUES(person.id,'నేటి పరిచయ పోటీ: తెలంగాణ '||(board->'totals'->>'TG')||', ఆంధ్రప్రదేశ్ '||(board->'totals'->>'AP')||' చేరికలు. '||CASE WHEN leader<>'' THEN 'ముందున్న వ్యక్తి: '||leader||'. ' ELSE '' END||'అనుమతించిన చిత్రాలు, తాజా స్థానాలు సమాచార పేజీలో చూడండి.') RETURNING id INTO notice; IF notice IS NOT NULL THEN UPDATE public.daily_referral_board_notices SET notification_id=notice WHERE user_id=person.id AND day=today; n:=n+1; END IF; END IF; END IF; END LOOP; RETURN n; END $$;